<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { Plus,PenLine,ArrowLeftRight,ChevronRight,ShieldCheck,Wallet,ClipboardList,Gavel,GraduationCap,Trash2,Settings } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import PageTitle from '../components/PageTitle.vue'
import StatusBadge from '../components/StatusBadge.vue'
import FileUpload from '../components/FileUpload.vue'
import { state,money,uid } from '../lib/store'
import { requireRole,confirm,notify } from '../lib/actions'
const router=useRouter(),edit=ref(false),adding=ref(false),settings=ref(false),name=ref(state.session.nickname),bio=ref(state.session.bio),work=ref({title:'',tool:'即梦 / 人工精修',hours:2}),files=ref([]),notification=ref(true),ai=ref(false)
function openEdit(){if(!requireRole(router,state.session.role))return;edit.value=true}
function save(){if(name.value.trim().length<2||name.value.trim().length>20){ElMessage.warning('昵称须为 2–20 字');return}state.session.nickname=name.value.trim();state.session.bio=bio.value;edit.value=false;notify('个人资料已保存')}
async function switchRole(){if(!state.session.loggedIn){router.push('/login');return}const target=state.session.role==='merchant'?'creator':'merchant';if(await confirm(`确认切换为${target==='merchant'?'商家':'创作者'}身份？订单与钱包按身份分别展示。`,'切换身份')){state.session.role=target;notify('演示身份已切换');router.push(target==='merchant'?'/merchant':'/creator/orders')}}
function add(){if(!requireRole(router,'creator'))return;if(state.portfolio.length>=30){ElMessage.warning('作品集最多 30 件');return}adding.value=true}
function publishWork(){if(!work.value.title.trim()||!files.value.length||!ai.value){ElMessage.warning('请填写作品标题、选择图片并勾选创作声明');return}state.portfolio.unshift({id:uid('P'),title:work.value.title,image:files.value[0].image,tool:work.value.tool,hours:work.value.hours,pending:true});adding.value=false;files.value=[];work.value.title='';notify('演示作品已保存为待审核状态，未上传服务器')}
async function remove(p){if(!requireRole(router,'creator'))return;if(await confirm(`从当前浏览器移除“${p.title}”？`,'移除作品'))state.portfolio=state.portfolio.filter(x=>x.id!==p.id)}
</script>
<template><main id="page-content" class="page-container app-ui"><PageTitle title="个人中心"><el-button @click="router.push(state.session.role==='merchant'?'/merchant':'/creator/orders')">返回工作台</el-button></PageTitle><div class="columns wide-left profile-columns"><div class="stack"><section class="panel profile-hero"><div class="profile-accent"><img src="/assets/task-square/chrome-banner.webp" alt=""/></div><div class="profile-top"><div class="person"><img class="avatar large" src="/assets/pages/creator-avatar.webp" alt="演示头像"/><div><h2 class="profile-name">{{state.session.nickname}}</h2><div class="tag-row"><span class="plain-tag">Lv.3 认证 · 示例</span><span class="plain-tag">信用分 100</span><StatusBadge :status="state.auth.personal"/></div><p>{{state.session.bio}}</p></div></div><div class="profile-controls"><el-button @click="openEdit"><PenLine/>编辑资料</el-button><el-button type="primary" plain @click="switchRole"><ArrowLeftRight/>切换为{{state.session.role==='merchant'?'创作者':'商家'}}</el-button></div></div><div class="profile-metrics"><div>累计成单<strong>{{state.orders.length}}</strong></div><div>好评率<strong>98%</strong></div><div>累计收入<strong class="price-text">¥{{money(state.earned)}}</strong></div><div>响应时长<strong>20 分钟</strong></div></div></section><section class="panel"><div class="panel-title"><div><h2>作品集</h2><span class="muted small">最多可添加 30 件作品，展示你的创作实力。</span></div><el-button type="primary" @click="add"><Plus/>添加作品</el-button></div><div class="portfolio-grid"><article v-for="p in state.portfolio" :key="p.id" class="portfolio-card"><div class="portfolio-image"><el-image v-if="p.image" :src="p.image" :preview-src-list="state.portfolio.filter(p=>p.image).map(p=>p.image)" preview-teleported :alt="p.title"/><div v-else class="portfolio-placeholder">本地文件预览已失效</div><span v-if="p.pending" class="ai-tag">AI 生成 · 待审核</span><button class="portfolio-delete" :aria-label="`移除${p.title}`" @click="remove(p)"><Trash2 :size="15"/></button></div><h3>{{p.title}}</h3><p>工具：{{p.tool}} · 工时：{{p.hours}} 小时</p></article></div><el-empty v-if="!state.portfolio.length" description="添加第一件作品，让商家了解你的创作风格"/></section></div><aside class="stack"><section class="panel"><h2>认证信息</h2><div class="data-lines"><div><label>实名认证</label><RouterLink to="/verification?tab=personal"><StatusBadge :status="state.auth.personal"/></RouterLink></div><div><label>企业认证</label><RouterLink to="/verification?tab=business"><StatusBadge :status="state.auth.business"/></RouterLink></div><div><label>银行卡</label><RouterLink to="/creator/wallet" class="text-link">{{state.bankBound?'演示已绑定':'去绑定'}}</RouterLink></div><div><label>可接单金额</label><strong>等级示例：不限</strong></div></div></section><section class="panel"><h2>快捷入口</h2><div class="profile-links"><RouterLink v-for="x in [['我的订单','/creator/orders',ClipboardList],['我的投标','/creator/bids',Gavel],['钱包','/creator/wallet',Wallet],['消息中心','/messages',ShieldCheck]]" :key="x[0]" :to="x[1]"><component :is="x[2]" :size="20"/><span>{{x[0]}}</span><ChevronRight :size="16"/></RouterLink><button @click="settings=true"><Settings :size="20"/><span>设置</span><ChevronRight :size="16"/></button></div></section><section class="panel"><h2>创作者学院</h2><div class="academy-placeholder"><GraduationCap :size="38"/><strong>敬请期待</strong><p>一起把灵感变成作品。</p></div></section></aside></div><el-dialog v-model="edit" title="编辑个人资料" width="500px" class="refinement-dialog"><div class="app-ui"><el-form label-position="top"><el-form-item label="昵称"><el-input v-model="name" maxlength="20" show-word-limit/></el-form-item><el-form-item label="个人简介"><el-input v-model="bio" type="textarea" :rows="3" maxlength="120" show-word-limit/></el-form-item></el-form></div><template #footer><el-button @click="edit=false">取消</el-button><el-button type="primary" @click="save">保存资料</el-button></template></el-dialog><el-dialog v-model="adding" title="添加作品" width="550px" class="refinement-dialog"><div class="app-ui"><el-form label-position="top"><el-form-item label="作品标题" required><el-input v-model="work.title" maxlength="30"/></el-form-item><el-form-item label="作品图片" required><FileUpload v-model="files" :limit="1" images-only label="选择作品"/></el-form-item><div class="form-grid"><el-form-item label="创作工具"><el-input v-model="work.tool" maxlength="40"/></el-form-item><el-form-item label="创作工时（小时）"><el-input-number v-model="work.hours" :min="0.5" :max="100" :step=".5"/></el-form-item></div><el-checkbox v-model="ai">作品为 AI 辅助生成并经人工精修，我拥有展示权。</el-checkbox></el-form></div><template #footer><el-button @click="adding=false">取消</el-button><el-button type="primary" @click="publishWork">保存为待审核（演示）</el-button></template></el-dialog><el-dialog v-model="settings" title="账号设置" width="480px" class="refinement-dialog"><div class="app-ui dialog-stack"><label class="inline-actions">接收站内提醒 <el-switch v-model="notification"/></label><p class="field-help">此开关仅控制本次演示偏好，未连接消息推送服务。</p><el-button @click="state.session.loggedIn=false;settings=false;router.push('/')">退出演示身份</el-button></div></el-dialog></main></template>
<style scoped>.profile-hero{position:relative;overflow:hidden;padding:25px 25px 20px 48px}.profile-accent{position:absolute;left:0;top:0;bottom:0;width:24px;background:#002bd7;overflow:hidden}.profile-accent>img{height:100%;width:180px;object-fit:cover;object-position:right;opacity:.8}.profile-top{display:flex;align-items:center;justify-content:space-between;gap:22px}.profile-top h1{font-size:27px;margin-bottom:7px}.profile-top .person{align-items:flex-start}.profile-top .person p{margin-top:10px;color:#5d697b;font-size:13px}.profile-controls{display:flex;flex-direction:column;gap:12px;flex-shrink:0}.profile-metrics{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid #e0e6ee;margin-top:24px;padding-top:22px;text-align:center;font-size:12px;color:#748096}.profile-metrics>div+div{border-left:1px solid #dfe5ef}.profile-metrics strong{display:block;font-size:26px;color:#202734;margin-top:4px}.profile-metrics strong.price-text{color:#ff4018}.portfolio-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.portfolio-card{border:1px solid #e0e5ee;border-radius:7px;overflow:hidden}.portfolio-image{position:relative}.portfolio-image>.el-image{width:100%;aspect-ratio:1.65;display:block}.portfolio-image :deep(.el-image__inner){object-fit:cover;object-position:left}.ai-tag{position:absolute;bottom:8px;left:8px;border-radius:4px;font-size:9px;color:#fff;background:#222a;pointer-events:none;padding:2px 6px}.portfolio-delete{position:absolute;top:8px;right:8px;background:#fffdfb;border-radius:4px;width:25px;height:25px;display:grid;place-items:center;color:#5e6a7f}.portfolio-card h3{font-size:13px;margin:10px 10px 5px}.portfolio-card p{font-size:9px;margin:0 10px 12px;color:#7e8797}.portfolio-placeholder{background:#f1f4fb;aspect-ratio:1.65;display:grid;place-items:center;font-size:10px;color:#8a95aa}.profile-links{display:grid}.profile-links>a,.profile-links>button{display:flex;align-items:center;gap:12px;padding:14px 0;border-bottom:1px solid #e6eaf1}.profile-links>*:last-child{border:0}.profile-links span{flex:1;text-align:left}.profile-links>*:hover{color:#002bd7}.academy-placeholder{height:170px;background:#edf2ff;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#7d8faf;gap:10px;border-radius:7px}.academy-placeholder strong{font-size:21px}.academy-placeholder p{font-size:11px;margin:0}@media(max-width:1250px){.profile-top{flex-wrap:wrap}.profile-controls{flex-direction:row}.profile-metrics strong{font-size:21px}.portfolio-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.profile-hero{padding:20px 16px 20px 30px}.profile-top .person{flex-wrap:wrap}.profile-top h1{font-size:24px}.profile-metrics{grid-template-columns:repeat(2,1fr);gap:20px}.profile-metrics>div:nth-child(3){border:0}.portfolio-grid{gap:10px}.portfolio-card h3{font-size:12px}.portfolio-card p{font-size:9px}.profile-controls{flex-wrap:wrap}.panel-title{flex-wrap:wrap}}
</style>
